"""Author-written preparation before every module's mixed and coding practice.

The two task-specific hints are methods of approach, not answer keys. Keep
them aligned with the stable p06/p07 task ids (saved progress depends on ids).
"""


def P(number, why, steps, code, result, first, second, *, language='java', runnable=False, label='Фрагмент для main'):
    assert 70 <= len(why) <= 480, (number, why)
    assert 2 <= len(steps) <= 4 and all(55 <= len(step) <= 360 for step in steps), (number, steps)
    assert len(code.strip()) >= 40 and 30 <= len(result) <= 400, (number, code, result)
    assert all(65 <= len(hint) <= 330 for hint in (first, second)), (number, first, second)
    assert language in {'java', 'sql', 'xml', 'yaml', 'dockerfile', 'text'}
    if runnable:
        assert language == 'java' and 'public class Main {' in code and 'public static void main(String[] args)' in code
    return dict(why=why, steps=list(steps),
                example=dict(code=code, language=language, runnable=runnable, label=label),
                result=result,
                hints=[dict(taskId=f'm{number:02}-p06', text=first),
                       dict(taskId=f'm{number:02}-p07', text=second)])


